+{
+  "id": "guardrail-bridge",
+  "name": "Guardrail Bridge",
+  "description": "Pre-agent guardrail-bridge plugin with blacklist and HTTP connectors.",
+  "activation": {
+    "onStartup": true
+  },
+  "uiHints": {
+    "http.apiKey": {
+      "label": "Guardrail HTTP API Key",
+      "help": "Use an OpenClaw SecretRef when possible; plain string values are supported but not recommended. SecretRef values are resolved at request time, not during plugin registration.",
+      "sensitive": true
+    },
+    "channels.*.http.apiKey": {
+      "label": "Channel Guardrail HTTP API Key",
+      "help": "Channel-specific OpenClaw SecretRef or plain string API key. SecretRef values are resolved at request time. Channel keys do not inherit across provider/apiUrl retargets unless explicitly configured.",
+      "sensitive": true
+    }
+  },
+  "configSchema": {
+    "type": "object",
+    "additionalProperties": false,
+    "properties": {
+      "connector": {
+        "type": "string",
+        "enum": ["", "blacklist", "http"],
+        "description": "Connector type for safety checks. Empty string or omitted = auto-detect from http/blacklist fields. Global connector is optional — channels can independently enable Guardrails."
+      },
+      "http": {
+        "type": "object",
+        "description": "HTTP engine configuration",
+        "additionalProperties": false,
+        "properties": {
+          "provider": {
+            "type": "string",
+            "description": "HTTP provider name. Built-in: 'dknownai', 'secra', 'hidylan'. Built-in apiKey behavior: 'dknownai' and 'secra' require apiKey; 'hidylan' currently treats apiKey as optional. Custom providers can be registered via registerHttpProvider()."
+          },
+          "apiKey": {
+            "type": ["string", "object"],
+            "description": "Provider API key as a plain string or OpenClaw SecretRef. SecretRef values are resolved at request time inside checks, not during plugin registration or provider init. Required by built-in 'dknownai' and 'secra'; optional for built-in 'hidylan'. Plain strings are supported but not recommended."
+          },
+          "apiUrl": {
+            "type": "string",
+            "description": "Endpoint URL. Optional override for built-in providers."
+          },
+          "model": {
+            "type": "string",
+            "default": "",
+            "description": "Model version. Current built-in 'dknownai', 'secra', and 'hidylan' ignore it; custom providers may use it."
+          },
+          "params": {
+            "type": "object",
+            "description": "Provider-specific parameters (project_id, region, etc.)",
+            "additionalProperties": true
+          }
+        }
+      },
+      "timeoutMs": {
+        "type": "number",
+        "minimum": 500,
+        "maximum": 30000,
+        "default": 5000
+      },
+      "fallbackOnError": {
+        "type": "string",
+        "enum": ["pass", "block"],
+        "default": "pass"
+      },
+      "blockMessage": {
+        "type": "string",
+        "default": "This request has been blocked by the guardrail-bridge policy."
+      },
+      "blacklist": {
+        "type": "object",
